export function computeInvoice(input = {}) {
  const { lines, discountKobo = 0 } = input ?? {};

  if (!Array.isArray(lines)) {
    throw new RangeError("lines must be an array");
  }

  if (!Number.isInteger(discountKobo) || discountKobo < 0) {
    throw new RangeError("discountKobo must be a non-negative integer");
  }

  // Keep all monetary arithmetic exact, including intermediate products.
  let subtotal = 0n;
  const rows = [];

  for (let index = 0; index < lines.length; index++) {
    const line = lines[index];
    const unitPriceKobo = line?.unitPriceKobo;
    const qty = line?.qty;

    if (!Number.isInteger(unitPriceKobo) || unitPriceKobo < 0) {
      throw new RangeError(
        `lines[${index}].unitPriceKobo must be a non-negative integer`
      );
    }

    if (!Number.isInteger(qty) || qty < 1) {
      throw new RangeError(
        `lines[${index}].qty must be a positive integer`
      );
    }

    const lineSubtotal = BigInt(unitPriceKobo) * BigInt(qty);
    subtotal += lineSubtotal;

    rows.push({
      sku: line.sku,
      vatExempt: line.vatExempt,
      subtotal: lineSubtotal,
      discount: 0n
    });
  }

  const requestedDiscount = BigInt(discountKobo);
  const appliedDiscount =
    requestedDiscount < subtotal ? requestedDiscount : subtotal;

  if (subtotal > 0n && appliedDiscount > 0n) {
    let allocated = 0n;

    const remainders = rows.map((row, index) => {
      const numerator = appliedDiscount * row.subtotal;
      row.discount = numerator / subtotal;
      allocated += row.discount;

      return { index, remainder: numerator % subtotal };
    });

    // The leftover is strictly smaller than the number of lines.
    const leftover = Number(appliedDiscount - allocated);

    if (leftover > 0) {
      remainders.sort((a, b) => {
        if (a.remainder > b.remainder) return -1;
        if (a.remainder < b.remainder) return 1;
        return a.index - b.index;
      });

      for (let index = 0; index < leftover; index++) {
        rows[remainders[index].index].discount += 1n;
      }
    }
  }

  let vatTotal = 0n;

  const computedLines = rows.map((row) => {
    const net = row.subtotal - row.discount;

    // 7.5% = 3/40; adding half the denominator rounds half up.
    const vat =
      row.vatExempt === false ? (net * 3n + 20n) / 40n : 0n;

    vatTotal += vat;

    return {
      sku: row.sku,
      subtotalKobo: Number(row.subtotal),
      discountKobo: Number(row.discount),
      netKobo: Number(net),
      vatKobo: Number(vat)
    };
  });

  return {
    subtotalKobo: Number(subtotal),
    discountKobo: Number(appliedDiscount),
    vatKobo: Number(vatTotal),
    totalKobo: Number(subtotal - appliedDiscount + vatTotal),
    lines: computedLines
  };
}
